import {cielo2civetFile} from 'cielo'

# ---------------------------------------------------------------------------
# Please, no dependencies on the directory structure!
# ---------------------------------------------------------------------------

export type TCompilerFunc = (path: string, hOptions: hash) => TExecResult
export type TPostProcessor = (path: string, hOptions: hash) => TExecResult

export type TCompilerInfo = {
	isInstalled: () => boolean
	compiler: TCompilerFunc
	getOutPaths: (path: string) => string[]
	}

export isCompilerInfo := (x: unknown): x is TCompilerInfo =>
	if (typeof x == 'object') && (x != null)
		return ('isInstalled' in x) && ('compiler' in x) && ('getOutPaths' in x)
	else
		return false

export type TCompilerConfig =
	hCompilers: hashof<TCompilerInfo> # <string>: <TCompilerInfo>
	hPostProcessors: hashof<TPostProcessor> # <string>: <TPostProcessor>

export isCompilerConfig := (x: unknown): x is TCompilerConfig =>
	if (typeof x == 'object') && (x != null)
		return ('hCompilers' in x) && ('hPostProcessors' in x)
	else
		return false

# ---------------------------------------------------------------------------
# ASYNC

export getCompilerInfo := (
		ext: string
		): TCompilerInfo? =>

	hConfig := await getCompilerConfig()
	return hConfig.hCompilers[ext]

# ---------------------------------------------------------------------------
# ASYNC

let cachedFileName: string? = undef
let hCachedConfig: TCompilerConfig? = undef

export getCompilerConfig := (
		fileName: string = 'compile.config.civet'
		): TCompilerConfig =>

	# --- if cached, return cached config
	if defined(hCachedConfig) && (fileName == cachedFileName)
		return hCachedConfig

	let hConfig = await configFromFile fileName

	DBGVALUE 'hConfig', hConfig
	assert isCompilerConfig(hConfig), "Bad compiler config: #{hConfig}"

	# --- Remove any compilers for which the
	#     compiler software has not been installed
	{hCompilers} := hConfig
	for ext of keys(hCompilers)
		{isInstalled} := hCompilers[ext]
		if not await isInstalled()
			DBG "Deleting compiler for ext #{OL(ext)}"
			delete hCompilers[ext]

	hCachedConfig = hConfig
	cachedFileName = fileName
	return hConfig

# ---------------------------------------------------------------------------
# ASYNC

export getPostProcessor := (
		purpose: string
		): TPostProcessor? =>

	hConfig := await getCompilerConfig()
	pp := hConfig.hPostProcessors[purpose]
	if defined(pp)
		return pp
	else
		DBG "No post processor for #{purpose} files"
		return undef

# ---------------------------------------------------------------------------

class CFileCompiler extends CFileHandler

	get op()
		return 'doCompileFile'

	# ..........................................................
	# ASYNC

	override async needed(
			path: string
			hOptions: hash = {}
			): boolean

		return true

	# ..........................................................

	postProcess(
			purpose: string
			path: string
			hOptions: hash = {}
			): TExecResult

		postProc := await getPostProcessor purpose
		if defined(postProc)
			DBG "post-processing file"
			try
				return await postProc(path, hOptions)
			catch err
				return {
					success: false
					stderr: getErrStr(err)
					}
		else
			return {
				success: true
				notNeeded: true
				}

	# ..........................................................
	# --- file existence has already been checked.

	override async handle(
			path: string
			hOptions: hash = {}
			): TExecResult

		DBG "COMPILE: #{OL(path)}", INDENT
		type opt = {
			nopp: boolean
			}
		{nopp} := getOptions<opt> hOptions, {
			nopp: false
			}

		{stub, purpose, ext} := parsePath path
		if notdefined(ext)
			DBG "Not compiling - no file extension in #{OL(path)}", UNDENT
			return {
				success: true
				notNeeded: true
				}

		hCompilerInfo := await getCompilerInfo ext
		if notdefined(hCompilerInfo)
			DBG "Not compiling - no compiler for ext #{OL(ext)}", UNDENT
			return {
				success: true
				notNeeded: true
				}

		{isInstalled, compiler, getOutPaths} := hCompilerInfo
		if not isInstalled()
			DBG "compiler for ext #{OL(ext)} not installed", UNDENT
			return {
				success: true
				notNeeded: true
				}

		lOutPaths := getOutPaths path
		DBG "lOutPaths = #{OL(lOutPaths)}"
		if allOf(lOutPaths, (p) => newerDestFileExists(path, p))
			hResult: TExecResult := {
				success: true
				notNeeded: true
				outfile: lOutPaths
				}
			if defined(purpose) && not nopp
				hResult.hPostResult = await @postProcess(purpose, path, hOptions)
			DBG "Not compiling, newer #{OL(lOutPaths)} exist", UNDENT
			return hResult

		DBG "compiling #{OL(path)} to #{OL(lOutPaths)}"
		hResult := compiler(path, hOptions)
		{success} := hResult

		if success && defined(purpose) && not nopp
			hResult.hPostResult = await @postProcess(purpose, path)

		DBG UNDENT
		return hResult

export doCompileFile := new CFileCompiler()

